#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/drivers/espi.h>
#include <zephyr/drivers/espi_saf.h>
#include "espi_utils.h"

#define LOG_LEVEL LOG_LEVEL_DBG
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(espi_test);

#define ESPI_DEV DT_COMPAT_GET_ANY_STATUS_OKAY(zephyr_espi_controller)

#define ESPI_PERIPHERAL_ACPI_EVT      ESPI_PERIPHERAL_INDEX(0)
#define ESPI_PERIPHERAL_ACPI_SHM      ESPI_PERIPHERAL_INDEX(1)

#define ACPI_SHM_SIZE 64

static struct espi_callback cb_data;
static struct espi_cfg cfg;

static void espi_test_init(void)
{
	int ret;

	cfg.channel_caps = ESPI_CHANNEL_VWIRE | ESPI_CHANNEL_OOB;
	cfg.periph_caps = ESPI_PERIPHERAL_ACPI_EVT | ESPI_PERIPHERAL_ACPI_SHM;
	cfg.io_caps = ESPI_IO_MODE_QUAD;

	ret = espi_config(ESPI_DEV, &cfg);
	zassert_equal(ret, 0, "eSPI config failed");
}

static void espi_test_callbacks(void)
{
	int ret;

	ret = espi_init_callback(&cb_data, espi_test_cb, ESPI_BUS_EVENT_CHANNEL_READY);
	zassert_equal(ret, 0, "eSPI init callback failed");

	ret = espi_add_callback(ESPI_DEV, &cb_data);
	zassert_equal(ret, 0, "eSPI add callback failed");

	ret = espi_remove_callback(ESPI_DEV, &cb_data);
	zassert_equal(ret, 0, "eSPI remove callback failed");
}

#if DT_NODE_HAS_STATUS(DT_NODELABEL(espi_acpi_shm), okay)
static void espi_test_acpi_shared_memory(void)
{
	const struct device *dev = DEVICE_DT_GET(DT_NODELABEL(espi_acpi_shm));
	uint8_t shm_data[ACPI_SHM_SIZE];
	uint8_t verify_data[ACPI_SHM_SIZE];
	int ret;

	zassert_true(device_is_ready(dev), "ACPI SHM device not ready");

	/* Test case: read/write ACPI shared memory */
	ret = espi_read_acpi_shm(dev, 0, sizeof(shm_data), shm_data);
	zassert_equal(ret, 0, "Failed to read ACPI shared memory");

	/* Modify data and write back */
	shm_data[0]++;
	ret = espi_write_acpi_shm(dev, 0, sizeof(shm_data), shm_data);
	zassert_equal(ret, 0, "Failed to write ACPI shared memory");

	/* Read back and verify */
	ret = espi_read_acpi_shm(dev, 0, sizeof(verify_data), verify_data);
	zassert_equal(ret, 0, "Failed to read back ACPI shared memory");
	zassert_mem_equal(shm_data, verify_data, sizeof(shm_data), "Data mismatch");
}
#endif /* DT_NODE_HAS_STATUS(DT_NODELABEL(espi_acpi_shm), okay) */

static void *espi_api_setup(void)
{
	zassert_true(device_is_ready(ESPI_DEV), "eSPI device not ready");
	return NULL;
}

ZTEST(espi_api, test_espi_config)
{
	espi_test_init();
}

ZTEST(espi_api, test_espi_callbacks)
{
	espi_test_callbacks();
}

#if DT_NODE_HAS_STATUS(DT_NODELABEL(espi_acpi_shm), okay)
ZTEST(espi_api, test_acpi_shared_memory)
{
	espi_test_acpi_shared_memory();
}
#endif /* DT_NODE_HAS_STATUS(DT_NODELABEL(espi_acpi_shm), okay) */


ZTEST_SUITE(espi_api, NULL, espi_api_setup, NULL, NULL, NULL);
